#!/usr/bin/env python3
import csv, json, sys, os, glob
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, encoding='utf-8-sig', newline='') as f:
        return f.read()


def csv_rows(path, delimiter=','):
    text = read_text(path)
    lines = [l for l in text.splitlines() if l.strip()]
    rdr = csv.reader(lines, delimiter=delimiter)
    rows = list(rdr)
    if not rows:
        return []
    hdr = [h.strip() for h in rows[0]]
    out = []
    for r in rows[1:]:
        out.append({hdr[i]: (r[i].strip() if i < len(r) else '') for i in range(len(hdr))})
    return out


def to_ts(dt):
    return int(dt.astimezone(UTC).timestamp()) if dt.tzinfo else None


def local_to_ts(naive, tz, dst_hint=None):
    """Naive local time -> epoch seconds. dst_hint True/False picks among repeated times;
    None -> first occurrence."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    chosen = a
    if a.utcoffset() != b.utcoffset() and dst_hint is not None:
        for c in (a, b):
            if bool(c.dst()) == dst_hint:
                chosen = c
                break
    return int(chosen.timestamp())


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s)


def read_site(site, tz, fmt, d):
    punches = []  # (id, emp, dir, ts)
    files = sorted(p for p in glob.glob(os.path.join(d, '**', '*'), recursive=True) if os.path.isfile(p))
    for p in files:
        if fmt == 'abbr-csv':
            for r in csv_rows(p):
                m, dd, y = r['Date'].split('/')
                t, ap = r['Time'].split()
                h, mi, s = (int(x) for x in t.split(':'))
                h = h % 12 + (12 if ap.upper() == 'PM' else 0)
                naive = datetime(int(y), int(m), int(dd), h, mi, s)
                z = r.get('Zone', '').upper()
                hint = True if z.endswith('DT') else (False if z.endswith('ST') else None)
                punches.append((r['Record'], r['Badge'], r['Punch'].upper(), local_to_ts(naive, tz, hint)))
        elif fmt == 'epoch-jsonl':
            for line in read_text(p).splitlines():
                if not line.strip():
                    continue
                o = json.loads(line)
                if o.get('heartbeat') or 'id' not in o:
                    continue
                ts = int(o['ts']) if 'ts' in o else int(o['ts_ms']) // 1000
                punches.append((str(o['id']), o['emp'], o['dir'].upper(), ts))
        elif fmt == 'offset-csv':
            for r in csv_rows(p, ';'):
                ev = r['event'].lower()
                punches.append((r['punch_id'], r['employee'], 'IN' if ev == 'clock_in' else 'OUT',
                                to_ts(parse_iso(r['timestamp']))))
        elif fmt == 'legacy-fixed':
            std = None
            for line in read_text(p).splitlines():
                if not line.startswith('D') or len(line) < 31:
                    continue
                pid = line[1:9]
                badge = line[9:15].strip()
                dr = line[15]
                dt = line[16:30]
                naive = datetime(int(dt[0:4]), int(dt[4:6]), int(dt[6:8]), int(dt[8:10]), int(dt[10:12]), int(dt[12:14]))
                loc = naive.replace(tzinfo=tz)
                stdoff = loc.utcoffset() - loc.dst()
                ts = int((naive - stdoff).replace(tzinfo=UTC).timestamp())
                punches.append((pid, 'E' + badge, 'IN' if dr == 'I' else 'OUT', ts))
        elif fmt == 'de-tsv':
            for r in csv_rows(p, '\t'):
                dd, mm, y = r['Datum'].split('.')
                h, mi = r['Uhrzeit'].split(':')[:2]
                naive = datetime(int(y), int(mm), int(dd), int(h), int(mi))
                z = r.get('Zeitzone', '').upper()
                hint = True if z == 'MESZ' else (False if z == 'MEZ' else None)
                punches.append((r['Nr'], r['Ausweis'], 'IN' if r['Buchung'].upper() == 'K' else 'OUT',
                                local_to_ts(naive, tz, hint)))
        elif fmt == 'local-csv':
            for r in csv_rows(p):
                naive = datetime.strptime(r['local_time'], '%Y-%m-%d %H:%M:%S')
                punches.append((r['punch_ref'], r['employee_id'], r['direction'].upper(), local_to_ts(naive, tz)))
        elif fmt == 'local-jsonl':
            for line in read_text(p).splitlines():
                if not line.strip():
                    continue
                o = json.loads(line).get('punch')
                if not o:
                    continue
                naive = datetime.strptime(o['at'], '%Y-%m-%d %H:%M:%S')
                punches.append((str(o['id']), o['badge'], o['type'].upper(), local_to_ts(naive, tz)))
