        a = c['action'].strip().lower()
        if a == 'void':
            if k in P:
                del P[k]
                applied += 1
        elif a == 'set':
            if k in P:
                P[k][2] = to_ts(parse_iso(c['time']))
                applied += 1
        elif a == 'add':
            if k not in existed:
                existed.add(k)
                P[k] = [c['employee'].strip(), c['type'].strip().upper(), to_ts(parse_iso(c['time']))]
                applied += 1

