        s = (ts + off) % 360
        return ts - s if s < 180 else ts + 360 - s

    stats = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0)) for e in emp_home}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    def workday(ts, home):
        return datetime.fromtimestamp(ts, home).date()

    for emp, lst in byemp.items():
        home = sites[emp_home[emp]][0]
        lst.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        kept = []
        last = None
        for ts, _, site, pid, dr in lst:
            rts = rnd(ts, sites[site][0])
            if last is not None and last[1] == dr and ts - last[0] <= 300:
                if pstart <= workday(rts, home) <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            last = (ts, dr)
            kept.append((rts, dr, site))
        shifts = []
        i = 0
        n = len(kept)
        while i < n:
            rts, dr, site = kept[i]
            wd = workday(rts, home)
            inp = pstart <= wd <= pend
            if dr == 'OUT':
                if inp:
                    exc['orphan_outs'] += 1
                i += 1
            elif i + 1 < n and kept[i + 1][1] == 'OUT' and kept[i + 1][0] - rts <= 57600:
                if inp:
                    shifts.append((rts, kept[i + 1][0], site, wd))
                i += 2
            else:
                if inp:
                    exc['open_shifts'] += 1
                i += 1
        shifts.sort(key=lambda s: s[0])
        # per shift minutes
        recs = []
        for a, b, site, wd in shifts:
            tz = sites[site][0]
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = 0
            for t in range(a, b, 60):
                h = datetime.fromtimestamp(t, tz).hour
                if h >= 22 or h < 6:
                    night += 1
            night = min(night, paid)
            recs.append([wd, paid, night, 0, 0])
        daycum = {}
        for r in recs:
            before = daycum.get(r[0], 0)
            after = before + r[1]
            daycum[r[0]] = after
            r[3] = max(0, after - 480) - max(0, before - 480)
        weekcum = {}
        for r in recs:
            wk = r[0] - timedelta(days=r[0].weekday())
            reg = r[1] - r[3]
            before = weekcum.get(wk, 0)
            after = before + reg
            weekcum[wk] = after
            r[4] = max(0, after - 2400) - max(0, before - 2400)
        st = stats[emp]
