            ot = dot + wot
            rate = Fraction(0)
            for eff, rt in rates.get(emp, []):
                if eff <= wd:
                    rate = rt
            st['shifts'] += 1
            st['paid_minutes'] += paid
            st['overtime_minutes'] += ot
            st['night_minutes'] += night
            st['gross'] += rate * (Fraction(paid - ot) + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60

    def money(fr):
        cents = (fr * 100 + Fraction(1, 2)).__floor__()
        return '%d.%02d' % (cents // 100, cents % 100)

    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totc = 0
    out_emp = {}
    for e in emp_home:
        s = stats[e]
        g = money(s['gross'])
        totc += int(g.replace('.', ''))
        for k in tot:
            tot[k] += s[k]
        out_emp[e] = {k: s[k] for k in tot}
        out_emp[e]['gross'] = g
    tot['gross'] = '%d.%02d' % (totc // 100, totc % 100)
    res = dict(period={'start': period['start'], 'end': period['end']}, employees=out_emp, exceptions=exc, totals=tot)
    with open(outf, 'w') as f:
        json.dump(res, f, indent=1)


main()
